	var wg sync.WaitGroup
	allowed := make(chan struct{}, 1000)
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(clock.Now(), 1) {
				allowed <- struct{}{}
			}
		}()
	}
	wg.Wait()
	close(allowed)
	if n := len(allowed); n != 1000 {
		t.Fatalf("allowed %d requests, want 1000 (full bucket)", n)
	}
	if got := l.Tokens(clock.Now()); got != 0 {
		t.Fatalf("tokens = %v, want 0", got)
	}
